        glm::ivec3 cell = glm::ivec3(pi->position.x / h, pi->position.y / h, pi->position.z / h);

        // Check all neighbors in the surrounding cells
        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                for (int z = -1; z <= 1; z++) {
                    glm::ivec3 neighborCell = cell + glm::ivec3(x, y, z);
                    uint32_t hash = (uint32_t)((neighborCell.x * 73856093) ^ (neighborCell.y * 19349663) ^ (neighborCell.z * 83492791)) % 262144;

                    // Get the index from the hash table
                    uint32_t index = particleTable[hash];
                    if (index == 0xFFFFFFFF) continue;

                    Particle *pj = &particles[index];

                    // Calculate distance between particles
                    glm::vec3 diff = pi->position - pj->position;
                    float dist = glm::length(diff);

                    // Only consider particles within the smoothing radius
                    if (dist > 0.0f && dist < h) {
                        // Pressure force calculation
                        glm::vec3 dir = glm::normalize(diff);
                        float pressureFactor = (pi->pressure + pj->pressure) / (2.0f * pj->density);
                        glm::vec3 pressureForce = -dir * mass * pressureFactor * spikyGrad * (h - dist) * (h - dist);

                        // Viscosity force calculation
                        glm::vec3 velocityDiff = pj->velocity - pi->velocity;
                        glm::vec3 viscosityForce = viscosity * mass * (velocityDiff / pj->density) * spikyLap * (h - dist);

                        // Add forces to particle
                        pi->force += pressureForce + viscosityForce;
                    }
                }
            }
        }
    }
